function requiredItems(){const w=current(),items=[];w.required.forEach(id=>{if(!value(id))items.push({type:'Detail',text:D.fields[id][0],target:`#fact-${id}`})});w.questions.forEach(q=>{if(!qvalue(q.id))items.push({type:'Question',text:q.label,target:`#question-${q.id}`})});w.systems.filter(s=>s.required).forEach(sys=>{if(!systemComplete(sys))items.push({type:'System',text:`${sys.label} finding`,target:'#systemsSection'})});applicableActions().filter(a=>a.required).forEach(a=>{const s=actionState(a.id);if(!s.status||(s.status==='na'&&!s.note.trim()))items.push({type:'Checklist',text:a.text,target:'#checklistSection'})});if(!state.contactStatus)items.push({type:'Response',text:'Customer contact status',target:'#responseSection'});if(!state.responseReviewed)items.push({type:'Response',text:'Customer response review',target:'#responseSection'});if(!state.outcome)items.push({type:'Closeout',text:'Outcome',target:'#responseSection'});if(!state.causeCode&&state.outcome&&state.outcome!=='Awaiting customer')items.push({type:'Closeout',text:'Cause Code',target:'#responseSection'});if(!state.resolutionSummary&&state.outcome)items.push({type:'Closeout',text:'Resolution / handoff summary',target:'#responseSection'});return items}
function renderProgress(){const items=requiredItems(),w=current(),total=w.required.length+w.questions.length+w.systems.filter(s=>s.required).length+applicableActions().filter(a=>a.required).length+3,complete=Math.max(0,total-items.length),pct=Math.max(0,Math.min(100,Math.round(complete/Math.max(total,1)*100)));$('#topIncident').textContent=value('incidentNumber')?`Incident ${value('incidentNumber')}`:'New ticket';$('#topProgress').textContent=items.length?`${items.length} left`:'Ready to review';$('#detailsStatus').textContent=`${w.required.filter(id=>value(id)).length+w.questions.filter(q=>qvalue(q.id)).length} / ${w.required.length+w.questions.length}`;$('#systemsStatus').textContent=`${w.systems.filter(s=>s.required&&systemComplete(s)).length} / ${w.systems.filter(s=>s.required).length}`;$('#actionsStatus').textContent=`${applicableActions().filter(a=>a.required&&actionState(a.id).status).length} / ${applicableActions().filter(a=>a.required).length}`;$('#responseStatus').textContent=state.responseReviewed&&state.contactStatus&&state.outcome?'Complete':'Open';['detailsStatus','systemsStatus','actionsStatus','responseStatus'].forEach(id=>$('#'+id).classList.toggle('complete',$('#'+id).textContent==='Complete'||!$('#'+id).textContent.includes('0 /')));renderNext(items);renderSnapshot();renderRequired(items);renderTicketDrawer();renderTicketDraftChecks()}
