function renderBuilder(){if(!state.builderBlocks.length&&!state.builderBlank)state.builderBlocks=builderDefaultBlocks();const c=$('#builderBlocks');if(!c)return;c.innerHTML='';state.builderBlocks.forEach((b,i)=>{const d=document.createElement('article');d.className='builder-block';d.innerHTML=`<div class="builder-block-head"><input value="${esc(b.type)}" aria-label="Block ${i+1} label"><div class="builder-controls"><button data-up aria-label="Move block ${i+1} up">Move up</button><button data-down aria-label="Move block ${i+1} down">Move down</button><button data-remove aria-label="Remove block ${i+1}">Remove</button></div></div><textarea aria-label="Block ${i+1} text">${esc(b.text)}</textarea><span class="block-source">Source: ${esc(b.source)}</span>`;const [label,area]=$$('input,textarea',d);label.oninput=()=>b.type=label.value;area.oninput=()=>b.text=area.value;$('[data-up]',d).onclick=()=>{if(i){[state.builderBlocks[i-1],state.builderBlocks[i]]=[state.builderBlocks[i],state.builderBlocks[i-1]];renderBuilder()}};$('[data-down]',d).onclick=()=>{if(i<state.builderBlocks.length-1){[state.builderBlocks[i+1],state.builderBlocks[i]]=[state.builderBlocks[i],state.builderBlocks[i+1]];renderBuilder()}};$('[data-remove]',d).onclick=()=>{state.builderBlocks.splice(i,1);renderBuilder()};c.append(d)});fillSelect($('#builderTemplate'),replyCatalog().filter(x=>x.audience==='Customer'&&x.status!=='sensitive').map(x=>x.title),'Select a message');const chips=$('#factChips');chips.innerHTML='';current().facts.filter(id=>value(id)).forEach(id=>{const b=document.createElement('button');b.textContent=D.fields[id][0];b.onclick=()=>{const text=`${D.fields[id][0]}: ${value(id)}`,last=state.builderBlocks[state.builderBlocks.length-1];if(last)last.text+=(last.text?'\n':'')+text;else state.builderBlocks.push({id:uid(),type:'Custom',text,source:'Ticket fact'});renderBuilder()};chips.append(b)});$('#builderOutput').value=state.builderOutput;$('#builderSourceSummary').textContent=`${state.builderBlocks.length} editable blocks. Sources include ticket facts, verified findings, procedures, messages, and custom text.`;renderMessageDraftChecks()}
