function replyStatusLabel(status){return({'customer-approved':'Quick message','internal-note':'Ivanti note','review-pending':'Review before use','evidence-gated':'Verify ticket facts','fragment':'Response fragment','incident-specific':'Incident-specific','county-specific':'County-specific','sensitive':'Restricted'})[status]||'Quick message'}
