function renderReplies(){const customer=state.replyMode==='Customer';$$('[data-reply-mode]').forEach(b=>b.classList.toggle('active',b.dataset.replyMode===state.replyMode));$('#replyModeHelp').innerHTML=customer?'<strong>Customer Email:</strong> Search customer-ready wording, then edit and review the assembled draft.':'<strong>Ivanti Note:</strong> Search internal documentation wording. Never send these notes directly to the customer.';const catalog=replyCatalog(),modeItems=catalog.filter(x=>x.audience===state.replyMode&&x.status!=='sensitive'),intents=unique(modeItems,'intent');$('#replyIntentChips').innerHTML=`<button class="${!state.replyIntent?'active':''}" data-intent="">All</button>`+intents.map(i=>`<button class="${state.replyIntent===i?'active':''}" data-intent="${esc(i)}">${esc(intentLabels[i]||i)}</button>`).join('');$$('[data-intent]').forEach(b=>b.onclick=()=>{state.replyIntent=b.dataset.intent;renderReplies()});const q=$('#replySearch').value.trim().toLowerCase(),favOnly=$('#replyFavoritesOnly')?.checked,items=modeItems.filter(x=>(!state.replyIntent||x.intent===state.replyIntent)&&(!favOnly||state.favoriteReplies.has(x.id))&&(!q||JSON.stringify(x).toLowerCase().includes(q))).sort((a,b)=>Number(state.favoriteReplies.has(b.id))-Number(state.favoriteReplies.has(a.id))||a.title.localeCompare(b.title));$('#replyCount').textContent=`${items.length} messages`;const c=$('#replyCards');c.innerHTML='';items.forEach(x=>{const a=document.createElement('article');a.className='item-card reply-card';const statusClass=String(x.status||'').replace(/[^a-z0-9-]/gi,'-'),fav=state.favoriteReplies.has(x.id);a.innerHTML=`<div class="reply-card-title"><h3>${esc(x.title)}</h3><button class="favorite-button ${fav?'active':''}" data-favorite aria-pressed="${fav}" aria-label="${fav?'Remove from':'Add to'} favorites">${fav?'★':'☆'}</button></div><div class="item-meta">${esc(intentLabels[x.intent]||x.intent)} <span class="reply-status ${esc(statusClass)}">${esc(replyStatusLabel(x.status))}</span></div><div class="source-text">${esc(x.text)}</div><div class="item-actions"><button class="primary" data-add>Add to draft</button><button class="secondary" data-builder>Add to builder</button><button class="secondary" data-copy>Copy</button></div>`;$('[data-favorite]',a).onclick=()=>{state.favoriteReplies.has(x.id)?state.favoriteReplies.delete(x.id):state.favoriteReplies.add(x.id);savePreferences();renderReplies()};$('[data-add]',a).onclick=()=>{if(!currentReplyKit().some(y=>y.id===x.id))currentReplyKit().push(x);state.messageWorkspace='quick';renderMessages()};$('[data-builder]',a).onclick=()=>{state.messageWorkspace='builder';addBuilderBlock(x.intent,x.text,'Quick Message');renderMessages()};$('[data-copy]',a).onclick=()=>copyDraftWithReview(x.text,x.audience);c.append(a)});renderReplyKit();renderReplySuggestions();renderMessageDraftChecks()}
function renderReplySuggestions(){const terms={registration:['registration','bar'],access:['password','account'],filing:['filing','docket','submission'],cases:['eservice','case'],upload:['troubleshooting','upload','pdf'],payment:['payment','fee'],correction:['correction','clerk'],technical:['escalat','technical'],clerk:['clerk','docket']}[state.workflow]||[];const catalog=replyCatalog().filter(x=>x.audience===state.replyMode&&x.status!=='sensitive');const items=catalog.filter(x=>terms.some(t=>`${x.title} ${x.intent} ${x.text}`.toLowerCase().includes(t))).slice(0,4);$('#suggestedReplies').innerHTML=items.length?items.map(x=>`<div class="suggestion-pill"><strong>${esc(x.title)}</strong><button class="secondary" data-rsuggest="${esc(x.id)}">Add</button></div>`).join(''):'<div class="info">No directly mapped quick messages. Search the library by what you need to do.</div>';$$('[data-rsuggest]').forEach(b=>b.onclick=()=>{const x=replyCatalog().find(y=>y.id===b.dataset.rsuggest);if(x&&!currentReplyKit().some(y=>y.id===x.id))currentReplyKit().push(x);renderReplyKit()})}
function renderReplyKit(){const c=$('#replyKit');if(!c)return;c.innerHTML='';currentReplyKit().forEach((x,i)=>{const d=document.createElement('div');d.className='kit-item';d.innerHTML=`<div class="kit-head"><strong>${i+1}. ${esc(x.title)}</strong><div class="kit-controls"><button data-up aria-label="Move ${esc(x.title)} up">Move up</button><button data-down aria-label="Move ${esc(x.title)} down">Move down</button><button data-remove aria-label="Remove ${esc(x.title)}">Remove</button></div></div>`;$('[data-up]',d).onclick=()=>{if(i){[currentReplyKit()[i-1],currentReplyKit()[i]]=[currentReplyKit()[i],currentReplyKit()[i-1]];renderReplyKit()}};$('[data-down]',d).onclick=()=>{if(i<currentReplyKit().length-1){[currentReplyKit()[i+1],currentReplyKit()[i]]=[currentReplyKit()[i],currentReplyKit()[i+1]];renderReplyKit()}};$('[data-remove]',d).onclick=()=>{currentReplyKit().splice(i,1);renderReplyKit()};c.append(d)});if(!currentReplyKit().length)c.innerHTML='<div class="info">Choose Add to draft on any message, or start with the current ticket draft.</div>';$('#replyDraftTitle').textContent=state.replyMode==='Customer'?'Customer email draft':'Ivanti note draft';$('#replyDraft').value=state.replyDrafts[state.replyMode];renderMessageDraftChecks()}
