function renderTerms(){const catalog=D.terminology||D.glossary,q=$('#termSearch').value.trim().toLowerCase(),cat=$('#termCategory')?.value||'',letter=$('#termLetter')?.value||'';fillSelect($('#termCategory'),unique(catalog,'category'),'All term groups');const letterSel=$('#termLetter');if(letterSel&&letterSel.options.length===1)[...new Set(catalog.map(x=>x.term[0].toUpperCase()))].sort().forEach(l=>letterSel.add(new Option(l,l)));const items=catalog.filter(x=>(!q||JSON.stringify(x).toLowerCase().includes(q))&&(!cat||x.category===cat)&&(!letter||x.term[0].toUpperCase()===letter));$('#termCount').textContent=`${items.length} terms`;$('#termGrid').innerHTML=items.sort((a,b)=>a.term.localeCompare(b.term)).map(x=>`<article class="term-guide-card"><div class="term-guide-head"><div><span>${esc(x.category||'Term')}</span><h3>${esc(x.term)}</h3>${x.full&&x.full!==x.term?`<small>${esc(x.full)}</small>`:''}</div></div><p>${esc(x.definition)}</p>${x.why?`<div class="term-note"><strong>Why it matters</strong><span>${esc(x.why)}</span></div>`:''}${x.confuse?`<div class="term-note"><strong>Do not confuse</strong><span>${esc(x.confuse)}</span></div>`:''}<div class="system-pills">${(x.related||[]).map(r=>pill(r)).join('')}</div><div class="knowledge-actions"><button class="secondary" data-copy-term="${esc(x.term)}">Copy definition</button><button class="secondary" data-term-messages="${esc(x.term)}">Find Messages</button></div></article>`).join('');$$('[data-copy-term]',$('#termGrid')).forEach(b=>b.onclick=()=>{const x=catalog.find(y=>y.term===b.dataset.copyTerm);if(x)copy(`${x.term}${x.full&&x.full!==x.term?' — '+x.full:''}: ${x.definition}`)});$$('[data-term-messages]',$('#termGrid')).forEach(b=>b.onclick=()=>openMessagesFor(b.dataset.termMessages))}
